"use strict";(globalThis.webpackChunkgrc||=[]).push([[80095],{78200(e){e.exports=JSON.parse('[{"citeKey":"gonzalez2026chronologposter","slug":"gonzalez-2026-chronolog-tiered-log-ff8c","title":"ChronoLog: Distributed Shared Tiered Log Store","authors":["E. Gonzalez","K. Feng","I. Brodkin","K. Chard","A. Kougkas","X.-H. Sun"],"venue":"13th Greater Chicago Area Systems Research Workshop (GCASR 2026)","type":"Poster","entryType":"misc","date":"May, 2026","year":2026,"era":"iit","month":5,"hasAbstract":false,"links":{"poster":"https://gcasr.org/2026/pdfs/posters/ChronoLog_Poster_v6_crop%20-%20Kun%20Feng.pdf"},"_projectIds":["chronolog"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"feng2019niobe","slug":"feng-2019-niobe-19f9","title":"NIOBE: An Intelligent I/O Bridging Engine for Complex and Distributed Workflows","authors":["K. Feng","H. Devarajan","A. Kougkas","X.-H. Sun"],"venue":"The 7th IEEE International Conference on Big Data, 2019. pp. 493-502","type":"Conference","entryType":"inproceedings","date":"December, 2019","year":2019,"era":"iit","month":12,"doi":"10.1109/bigdata47090.2019.9006363","abstract":"In the age of data-driven computing, integrating High Performance Computing (HPC) and Big Data (BD) en- vironments may be the key to increasing productivity and to driving scientific discovery forward. Scientific workflows consist of diverse applications (i.e., HPC simulations and BD analysis) each with distinct representations of data that introduce a se- mantic barrier between the two environments. To solve scientific problems at scale, accessing semantically different data from different storage resources is the biggest unsolved challenge. In this work, we aim to address a critical question: \\"How can we exploit the existing resources and efficiently provide transparent access to data from/to both environments\\". We propose iNtelligent I/O Bridging Engine (NIOBE), a new data integration framework that enables integrated data access for scientific workflows with asynchronous I/O and data aggregation. NIOBE performs the data integration using available I/O resources, in contrast to existing optimizations that ignore the I/O nodes present on the data path. In NIOBE, data access is optimized to consider both the ongoing production and the consumption of the data in the future. Experimental results show that with NIOBE, an integrated scientific workflow can be accelerated by up to 10x when compared to a no-integration baseline and by up to 133% compared to other state-of-the-art integration solutions.","hasAbstract":true,"lede":"We aim to address a critical question: \\"How can we exploit the existing resources and efficiently provide transparent access to data from/to both environments\\".","links":{"pdf":"https://grc.iit.edu/papers/2019/feng-2019-niobe-19f9.pdf"},"tags":["Data Integration","Integrated Workflow","Data Aggregation","KVS","Parallel File System (PFS)"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"feng2018scidp","slug":"feng-2018-scidp-cdc6","title":"SciDP: Support HPC and Big Data Applications via Integrated Scientific Data Processing","authors":["K. Feng","X.-H. Sun","X. Yang","S. Zhou"],"venue":"The IEEE International Conference on Cluster Computing 2018 (Cluster\'18), Belfast, UK2018. pp. 114-123.","type":"Conference","entryType":"inproceedings","date":"September, 2018","year":2018,"era":"iit","month":9,"doi":"10.1109/cluster.2018.00023","abstract":"Modern High Performance Computing (HPC) ap- plications, such as Earth science simulations, produce large amounts of data due to the surging of computing power, while big data applications have become more compute-intensive due to increasingly sophisticated analysis algorithms. The needs of both HPC and big data technologies for advanced HPC and big data applications create a demand for integrated system support. In this study, we introduce Scientific Data Processing (SciDP) to support both HPC and big data applications via integrated scientific data processing. SciDP can directly process scientific data stored on a Parallel File System (PFS), which is typically deployed in an HPC environment, in a big data programming environment running atop Hadoop Distributed File System (HDFS). SciDP seamlessly integrates PFS, HDFS, and the widely-used R data analysis system to support highly efficient processing of scientific data. It utilizes the merits of both PFS and HDFS for fast data transfer, overlaps computing with data accessing, and integrates R into the data transfer process. Experimental results show that SciDP accelerates analysis and visualization of a production NASA Center for Climate Simulation (NCCS) climate and weather application by 6x to 8x when compared to existing solutions.","hasAbstract":true,"lede":"In this study, we introduce Scientific Data Processing (SciDP) to support both HPC and big data applications via integrated scientific data processing.","links":{"pdf":"https://grc.iit.edu/papers/2018/feng-2018-scidp-cdc6.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"yang2016visualizationadaptive","slug":"yang-2016-visualization-adaptive-4cd5","title":"Visualization and Adaptive Subsetting of Earth Science Data in HDFS - A Novel Data Analysis Strategy with Hadoop and Spark","authors":["X. Yang","S. Liu","K. Feng","S. Zhou","X.-H. Sun"],"venue":"6th IEEE International Conference on Big Data and Cloud Computing (BDCloud 2016), Atlanta, GA2016, pp. 89-96","type":"Conference","entryType":"inproceedings","date":"October, 2016","year":2016,"era":"iit","month":10,"doi":"10.1109/bdcloud-socialcom-sustaincom.2016.24","abstract":"Data analytics becomes increasingly important in big data applications. Adaptively subsetting large amounts of data to extract the interesting events such as the centers of hurricane or thunderstorm, statistically analyzing and visualizing the subset data, is an effective way to analyze ever-growing data. This is particularly crucial for analyzing Earth Science data, such as extreme weather. The Hadoop ecosystem (i.e., HDFS, MapReduce, Hive) provides a cost-efficient big data management environment and is being explored for analyzing big Earth Science data. Our study investigates the potential of a MapReduce-like paradigm to perform statistical calculations, and utilizes the calculated results to subset as well as visualize data in a scalable and efficient way. RHadoop and SparkR are deployed to enable R to access and process data in parallel with Hadoop and Spark, respectively. The regular R libraries and tools are utilized to create and manipulate images. Statistical calculations, such as maximum and average variable values, are carried with R or SQL. We have developed a strategy to conduct query and visualization within one phase, and thus significantly improve the overall performance in a scalable way. The technical challenges and limitations of both Hadoop and Spark platforms for R are also discussed.","hasAbstract":true,"lede":"Data analytics becomes increasingly important in big data applications.","links":{"pdf":"https://grc.iit.edu/papers/2016/yang-2016-visualization-adaptive-4cd5.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"eslami2015efficientdisk","slug":"eslami-2015-efficient-disk-fda9","title":"Efficient Disk-to-Disk Sorting: A Case Study in Decoupled Execution Paradigm","authors":["H. Eslami","A. Kougkas","M. Kotsifakou","T. Kasampalis","K. Feng","Y. Lu","W. D. Gropp","X.-H. Sun","Y. Chen","R. Thakur"],"venue":"Data Intensive Scalable Computing Systems Workshop (DISCS), in conjunction with ACM/IEEE SuperComputing 2015, Austin, TX, USA","type":"Workshop","entryType":"inproceedings","date":"November, 2015","year":2015,"era":"iit","month":11,"doi":"10.1145/2831244.2831249","hasAbstract":false,"links":{"pdf":"https://dl.acm.org/ft_gateway.cfm?ftid=1643727&id=2831249"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"feng2015fastfault","slug":"feng-2015-fast-fault-d4c7","title":"Fast Fault Injection and Sensitivity Analysis for Collective Communications","authors":["K. Feng","M. G. Venkata","D. Li","X.-H. Sun"],"venue":"IEEE International Conference on Cluster Computing 2015 (Cluster\'15), Chicago, IL, USA","type":"Conference","entryType":"inproceedings","date":"September, 2015","year":2015,"era":"iit","month":9,"doi":"10.1109/cluster.2015.31","abstract":"The collective communication operations, which are widely used in parallel applications for global commu- nication and synchronization are critical for application\'s performance and scalability. However, how faulty collective communications impact the application and how errors prop- agate between the application processes is largely unexplored. One of the critical reasons for this situation is the lack of fast evaluation method to investigate the impacts of faulty collective operations. The traditional random fault injection methods relying on a large amount of fault injection tests to ensure statistical significance require a significant amount of resources and time. These methods result in prohibitive evaluation cost when applied to the collectives. In this paper, we introduce a novel tool named Fast Fault Injection and Sensitivity Analysis Tool (FastFIT) to conduct fast fault injection and characterize the application sensitivity to faulty collectives. The tool achieves fast exploration by reducing the exploration space and predicting the application sensitivity using Machine Learning (ML) techniques. A basis for these techniques are implicit correlations between MPI semantics, application context, critical application features, and application responses to faulty collective communications. The experimental results show that our approach reduces the fault injection points and tests by 97% for represen- tative benchmarks (NAS Parallel Benchmarks (NPB)) and a realistic application (Large-scale Atomic/Molecular Massively Parallel Simulator (LAMMPS)) on a production supercomputer. Further, we statistically generalize the application sensitivity to faulty collective communications for these workloads, and present correlation between application features and the sen- sitivity.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2015/feng-2015-fast-fault-d4c7.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"feng2015iosig","slug":"feng-2015-iosig--5e1a","title":"IOSIG+: on the Role of I/O Tracing and Analysis for Hadoop Systems","authors":["B. Feng","X. Yang","K. Feng","Y. Yin","X.-H. Sun"],"venue":"IEEE International Conference on Cluster Computing 2015 (Cluster\'15), Chicago, IL, USA","type":"Conference","entryType":"inproceedings","date":"September, 2015","year":2015,"era":"iit","month":9,"doi":"10.1109/cluster.2015.17","abstract":"Hadoop, as one of the most widely accepted MapReduce frameworks, is naturally data-intensive. Its several dependent projects, such as Mahout and Hive, inherent this characteristic. Meanwhile I/O optimization becomes a daunting work, since applications\' source code is not always available. I/O traces for Hadoop and its dependents are increasingly important, because it can faithfully reveal intrinsic I/O behaviors without knowing the source code. This method can not only help to diagnose system bottlenecks but also further optimize performance. To achieve this goal, we propose a transparent tracing and analysis tool suite, namely IOSIG+, which can be plugged into Hadoop system. We make several contributions: 1) we describe our approach of tracing; 2) we release the tracer, which can trace I/O operations without modifying targets\' source code; 3) this work adopts several techniques to mitigate the introduced execution overhead at runtime; 4) we create an analyzer, which helps to discover new approaches to address I/O problems according to access patterns. The experimental results and analysis confirm its effectiveness and the observed overhead can be as low as 1.97%.","hasAbstract":true,"lede":"To achieve this goal, we propose a transparent tracing and analysis tool suite, namely IOSIG+, which can be plugged into Hadoop system.","links":{"pdf":"https://grc.iit.edu/papers/2015/feng-2015-iosig--5e1a.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"yin2014rethinkingkey","slug":"yin-2014-rethinking-key-484a","title":"Rethinking Key-Value Store for Parallel I/O Optimization","authors":["Y. Yin","A. Kougkas","K. Feng","H. Eslami","Y. Lu","X.-H. Sun","R. Thakur","W. D. Gropp"],"venue":"Data Intensive Scalable Computing Systems Workshop (DISCS), in conjunction with ACM/IEEE SuperComputing 2014, New Orleans, LA, USA","type":"Workshop","entryType":"inproceedings","date":"November, 2014","year":2014,"era":"iit","month":11,"doi":"10.1109/discs.2014.11","abstract":"Key-Value Stores (KVStore) are being widely used as the storage system for large-scale Internet services and cloud storage systems. However, they are rarely used in HPC systems, where parallel file systems (PFS) are the dominant storage systems. In this study, we carefully examine the architecture difference and performance characteristics of PFS and KVStore. We propose that it is valuable to utilize KVStore to optimize the overall I/O performance, especially for the workloads that PFS cannot handle well, such as the cases with hurtful data synchronization or heavy metadata operations. To verify this proposal, we conducted comprehensive experiments with several synthetic benchmarks, an I/O benchmark, and a real application. The results show that our proposal is promising.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2014/yin-2014-rethinking-key-484a.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"chen2014decoupledio","slug":"chen-2014-decoupled-io-8543","title":"Decoupled I/O for Data-Intensive High Performance Computing","authors":["C. Chen","Y. Chen","K. Feng","Y. Yin","H. Eslami","R. Thakur","X.-H. Sun","W. D. Gropp"],"venue":"Seventh International Workshop on Parallel Programming Models and Systems Software for High-End Computing (P2S2), in conjunction with the International Conference on Parallel Processing (ICPP-2014), Minneapolis, MN, USA","type":"Workshop","entryType":"inproceedings","date":"September, 2014","year":2014,"era":"iit","month":9,"doi":"10.1109/icppw.2014.48","hasAbstract":false,"links":{"pdf":"https://ieeexplore.ieee.org/iel7/7101393/7103416/07103466.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"he2014performanceaware","slug":"he-2014-performance-aware-5536","title":"Performance-Aware Data Placement in Hybrid Parallel File Systems","authors":["S. He","X.-H. Sun","B. Feng","K. Feng"],"venue":"14th International Conference on Algorithms and Architectures for Parallel Processing (ICA3PP), Dalian, China","type":"Conference","entryType":"inproceedings","date":"August, 2014","year":2014,"era":"iit","month":8,"doi":"10.1007/978-3-319-11197-1_43","abstract":"Hybrid parallel file systems (PFS), which consist of both HDD and SSD servers, provide a promising solution for data-intensive applications. In this study, we propose a performance-aware data place- ment (PADP) strategy to enable efficient data layout in hybrid PFSs. The basic idea of PADP is to dispatch data on different file servers with adaptive varied-size file stripes based on the server storage performance. By using an effective data access cost model and a linear programming optimization method, the appropriate stripe sizes for each file server are determined effectively. We have implemented PADP within OrangeFS, a widely used parallel file system in HPC domain. Experimental results of representative benchmark show that PADP can significantly improve the I/O performance of hybrid PFSs.","hasAbstract":true,"lede":"In this study, we propose a performance-aware data place- ment (PADP) strategy to enable efficient data layout in hybrid PFSs.","links":{"pdf":"https://grc.iit.edu/papers/2014/he-2014-performance-aware-5536.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"feng2013runtimesystem","slug":"feng-2013-runtime-system-77fc","title":"Runtime System Design of Decoupled Execution Paradigm for Data-Intensive High-End Computing (Poster Presentation)","authors":["K. Feng","Y. Yin","C. Chen","H. Eslami","X.-H. Sun","Y. Chen","R. Thakur","W. D. Gropp"],"venue":"IEEE International Conference on Cluster Computing 2013 (Cluster\'13), Indianapolis, IN, USA","type":"Poster","entryType":"inproceedings","date":"September, 2013","year":2013,"era":"iit","month":9,"doi":"10.1109/cluster.2013.6702642","hasAbstract":false,"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"he2013costaware","slug":"he-2013-cost-aware-c52e","title":"A Cost-Aware Region-Level Data Placement Scheme for Hybrid Parallel I/O Systems","authors":["S. He","X.-H. Sun","B. Feng","X. Huang","K. Feng"],"venue":"IEEE International Conference on Cluster Computing 2013 (Cluster\'13), Indianapolis, IN, USA","type":"Conference","entryType":"inproceedings","date":"September, 2013","year":2013,"era":"iit","month":9,"doi":"10.1109/cluster.2013.6702615","abstract":"Parallel I/O systems represent the most commonly used engineering solution to mitigate the performance mismatch between CPU and disk performance; however, parallel I/O sys- tems are application dependent and may not work well for certain data access requests. New emerging solid state drives (SSD) are able to deliver better performance but incur a high monetary cost. While SSDs cannot always replace HDDs, the hybrid SSD- HDD approach uniquely addresses common performance issues in parallel I/O systems. The performance of hybrid SSD-HDD architecture depends on the utilization of the SSD and scheduling of data placement. In this paper, we propose a cost-aware region- level (CARL) data placement scheme for hybrid parallel I/O systems. CARL divides large files into several small regions, calculates the region costs according to the data access patterns, and selectively places regions with high access costs onto the SSD- based file servers. We have implemented CARL under MPI-IO and the PVFS2 parallel file system environment. Experimental results of representative benchmarks show that CARL is both feasible and able to improve I/O performance significantly.","hasAbstract":true,"lede":"We propose a cost-aware region- level (CARL) data placement scheme for hybrid parallel I/O systems.","links":{"pdf":"https://grc.iit.edu/papers/2013/he-2013-cost-aware-c52e.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"}]')}}]);